n = 64

# Find non-edges
non_edges = []
for i in range(n):
    for j in range(i+1, n):
        if j not in adj[i]:
            non_edges.append((i,j))

def find_clique_of_size(k):
    s = Solver()
    x = [Bool(f'x_{i}') for i in range(n)]
    for i, j in non_edges:
        s.add(Or(Not(x[i]), Not(x[j])))
    s.add(PbGe([(x[i], 1) for i in range(n)], k))
    result = s.check()
    if result == sat:
        model = s.model()
        clique = [i for i in range(n) if model.evaluate(x[i])]
        return clique
    return None

